payload.text:
modal thêm mới theo schema này
{
  "title": "Bao Cao Ban Hang Hang Ngay Rut Gon",
  "type": "object",
  "properties": {
    "ngayBaoCao": {
      "type": "string",
      "format": "date",
      "description": "Ngày báo cáo (ví dụ: 2025-12-04)"
    },
    "tongKetToanDoi": {
      "type": "object",
      "description": "Báo cáo tổng hợp toàn đội (Giữ nguyên).",
      "properties": {
        "tongSoFOS": { "type": "integer", "description": "Tổng số nhân viên FOS hoạt động." },
        "tongSoMC": { "type": "integer", "description": "Tổng số Merchant (MC) toàn đội khai thác được." },
        "tongSoNTB": { "type": "integer", "description": "Tổng số New to Bank (NTB)." },
        "NSBQ_NTB": { "type": "number", "description": "Năng suất bình quân NTB." },
        "tongSoETB": { "type": "integer", "description": "Tổng số Existing to Bank (ETB)." },
        "NSBQ_ETB": { "type": "number", "description": "Năng suất bình quân ETB." },
        "tongSoAEPlus": { "type": "integer", "description": "Tổng số MC có đăng ký AE+." },
        "tyLePOS": { "type": "string", "description": "Tỷ lệ POS (ví dụ: '1/27')." },
        "tyLeActiveFOS": { "type": "string", "description": "Tỷ lệ FOS hoạt động (ví dụ: '9/9')." }
      },
      "required": ["tongSoFOS", "tongSoMC", "tongSoNTB", "NSBQ_NTB", "tongSoETB", "NSBQ_ETB"]
    },
    "baoCaoFOS": {
      "type": "array",
      "description": "Danh sách báo cáo chi tiết chỉ với thông số hiệu suất.",
      "items": {
        "type": "object",
        "properties": {
          "tenNhanVien": {
            "type": "string",
            "description": "Tên nhân viên (ví dụ: 'Quế', 'Toàn')."
          },
          "chiSoHieuSuat": {
            "type": "object",
            "description": "Thông số hiệu suất chi tiết (ví dụ: '2/8/50').",
            "properties": {
              "saleHomNay": {
                "type": "integer",
                "description": "**Số sale (MC/NTB/v.v.) đạt được trong ngày.**"
              },
              "saleTrongThang": {
                "type": "integer",
                "description": "**Tổng số sale đã đạt được trong tháng (MTD).**"
              },
              "chiTieu": {
                "type": "integer",
                "description": "**Chỉ tiêu cần đạt của loại hình sale này.**"
              }
            },
            "required": ["saleHomNay", "saleTrongThang", "chiTieu"]
          }
        },
        "required": ["tenNhanVien", "chiSoHieuSuat"]
      }
    }
  }
}
